# =================================================================== # Hybrid model from Ott's if os.path.exists("./data/bids/limited_energy/derivatives/models/hybrid_model_trace.nc"): idata = az.from_netcdf("./data/bids/limited_energy/derivatives/models/hybrid_model_trace.nc") traces['Context'] = idata else: # Define the priors: priors = { 'dv_23': bmb.Prior('Normal', mu=0, sigma=2), 'dv_14': bmb.Prior('Normal', mu=0, sigma=2), 'is_basic_1': bmb.Prior('Normal', mu=0, sigma=2), 'is_basic_2': bmb.Prior('Normal', mu=0, sigma=2), 'is_basic_3': bmb.Prior('Normal', mu=0, sigma=2), 'is_basic_4': bmb.Prior('Normal', mu=0, sigma=2), 'is_full_energy': bmb.Prior('Normal', mu=0, sigma=2), 'is_low_energy_LC': bmb.Prior('Normal', mu=0, sigma=2), 'is_low_energy_HC': bmb.Prior('Normal', mu=0, sigma=2), 'dv_23|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'dv_14|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'is_basic_1|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'is_basic_2|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'is_basic_3|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), 'is_basic_4|vpn': bmb.Prior('Normal', mu=0, sigma=bmb.Prior('HalfNormal', sigma=2)), }
hybrid_model = bmb.Model( "response ~ dv_23 + dv_14 + is_basic_1 + is_basic_2 + is_basic_3 + is_basic_4 + is_full_energy + is_low_energy_LC + is_low_energy_HC + " " + (dv_23 + dv_14 + is_basic_1 + is_basic_2 + is_basic_3 + is_basic_4|vpn)", beh_data, priors=priors, family="bernoulli" ) # Add the idata to the rest: traces['Context'] = hybrid_model.fit( draws=n_samples, tune=n_warmup, chains=n_chains, target_accept=0.85, idata_kwargs={"log_likelihood": True} ) # Get the predicted responses: hybrid_model.predict(traces['Context'], kind="response", inplace=True)
# Save the trace to file: az.to_netcdf(traces['Context'], "./data/bids/limited_energy/derivatives/models/hybrid_model_trace.nc")

model_comparison = az.compare(traces)

# Compute the LOO for each model and participants:
loo_results = {}
for model_name, idata in traces.items():
    loo_results[model_name] = az.loo(idata, pointwise=True)
loos_df = pd.DataFrame({
    "vpn": beh_data['vpn'],
    **{model_name: loo_results[model_name].loo_i for model_name in loo_results.keys()}
})
# Sum within subject:
loos_sub = loos_df.groupby('vpn').sum().reset_index()

# Generate posterior predictive samples for each model:
for model_name, idata in traces.items():
    try:
        y_pred = idata.posterior_predictive["y"].to_numpy()
    except KeyError:
        y_pred = idata.posterior_predictive["response"].to_numpy()
    # Calculate the match between those:
    matches = []
    for i in range(y_pred.shape[0]):
        for ii in range(y_pred.shape[1]):
            matches.append(beh_data["response"].to_numpy() == y_pred[i, ii, :])
    matches = np.array(matches)
    # Compute the proportion of match between observed and predicted responses:
    beh_data[f"Match_{model_name.lower()}"] = np.mean(matches, axis=0)

fig, ax = plt.subplot_mosaic("ABC;DDD", figsize=[A4_inches[0], 0.6*A4_inches[1]]) cmap = matplotlib.colormaps.get_cmap('Set3') colors = {key: cmap(i) for i, key in enumerate(["Offer", "CC", "FC", "Energy", "full"])} # ================================================ # fig-2A: model comparison: # elpd_loo bar plot with error bar ax["A"].bar( range(len(model_comparison)-1), model_comparison.iloc[1:]["elpd_diff"], yerr=model_comparison.iloc[1:]["dse"], color=[colors[key] for key in model_comparison.index[1:]] ) # Decoration ax["A"].set_xticks(range(len(model_comparison)-1)) ax["A"].set_xticklabels(model_comparison.index[1:], rotation=10) ax["A"].set_ylabel("Δ ELPD (LOO)") ax["A"].set_title("Fit loss per factor") ax["A"].spines[['right', 'top']].set_visible(False) ax["A"].text(-0.2, 1.05, "A", transform=ax["A"].transAxes, fontsize=16, fontweight='bold', va='top', ha='right' );
# ================================================ # fig-2C: returns from the reduced MDP: order = np.argsort([return_reduced[key] for key in return_reduced.keys()]) ax["B"].bar( np.array([key for key in return_reduced.keys()])[order], np.array([return_reduced[key] for key in return_reduced.keys()])[order], color=np.array([colors[key] for key in return_reduced.keys()])[order] ) # Decoration ax["B"].axhline(1-returns_stochastic/returns_optimal, color="grey", linestyle="--") ax["B"].set_ylabel("Loss in relative return") ax["B"].set_title("Return loss of reduced MDPs") ax["B"].spines[['right', 'top']].set_visible(False) ax["B"].set_ylim([0, 1]) ax["B"].text(-0.2, 1.05, "B", transform=ax["B"].transAxes, fontsize=16, fontweight='bold', va='top', ha='right' )
# ================================================ # fig-2B: returns from the preferences only: order = np.argsort([returns_pref[key] for key in returns_pref.keys()]) ax["C"].bar( np.array([key for key in returns_pref.keys()])[order], np.array([returns_pref[key] for key in returns_pref.keys()])[order], color=np.array([colors[key] for key in returns_pref.keys()])[order] ) ax["C"].axhline(1-returns_stochastic/returns_optimal, color="grey", linestyle="--") # Decoration ax["C"].set_xticks(range(len(returns_pref))) ax["C"].set_xticklabels(np.array([key for key in returns_pref.keys()])[order], rotation=30) ax["C"].set_ylabel("Loss in relative return") ax["C"].set_ylim([0, 1]) ax["C"].set_title("Return loss per factor") ax["C"].spines[['right', 'top']].set_visible(False) ax["C"].text(-0.2, 1.05, "C", transform=ax["C"].transAxes, fontsize=16, fontweight='bold', va='top', ha='right' )
# ================================================ # fig-2D: marginal proba under optimal policy vs preferences # Extract the preference parameters: pref_param = traces["Preference"].posterior["beta_pref"].mean(dim=["chain", "draw"]).values positions = np.array([0, 2, 4, 6, 10, 12, 16, 18, 22, 24, 26, 28, 30, 32, 34]) ax["D"].bar( positions, expit(pref_param), color=cmap(10), width=1, label='Estimated preferences', edgecolor="grey", linewidth=0.5 ) positions2 = np.array(positions)+1 ax["D"].bar( positions2, marginal_action_proba, color=cmap(9), width=1, label="Marginal action probability", edgecolor="grey", linewidth=0.5 ) # Decoration ax["D"].set_xticks(np.mean(np.array([positions, positions2]), axis=0)) [ 'is_1', 'is_2', 'is_3', 'is_4', 'is_lc', 'is_hc', 'is_lfc', 'is_hfc', 'e_is_0', 'e_is_1', 'e_is_2', 'e_is_3', 'e_is_4', 'e_is_5', 'e_is_6' ] ax["D"].set_xticklabels(["O=1", "O=2", "O=3", "O=4", "CC=1", "CC=2", "FC=1", "FC=2", "E=0", "E=1", "E=2", "E=3", "E=4", "E=5", "E=6"], rotation=20) ax["D"].set_ylabel("P(A=1)") ax["D"].set_title("Estimated preferences vs. Marignal probability under optimal policy") ax["D"].spines[['right', 'top']].set_visible(False) ax["D"].legend(frameon=False) ax["D"].text(-0.05, 1.05, "D", transform=ax["D"].transAxes, fontsize=16, fontweight='bold', va='top', ha='right' )
plt.tight_layout();
